                return e
        return None

    # Basic movement: move towards nearest resource or opponent depending on mode
    dx, dy = 0, 0

    # Function to get Manhattan distance
    def distance(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    # Initialize target position
    target_x, target_y = None

    if mode == 'resource_collection':
        # Move towards the nearest resource
        min_dist = float('inf')
        for res in resources:
            rx, ry = res.get('x'), res.get('y')
            dist = distance(my_x, my_y, rx, ry)
