                target_x, target_y = rx, ry
        # If no resources, stay put
        if target_x is not None:
            dx = 0 if my_x == target_x else (1 if target_x > my_x else -1)
            dy = 0 if my_y == target_y else (1 if target_y > my_y else -1)
        else:
