            dx, dy = 0, 0

    elif mode == 'territory_control':
        # Move towards the edge of own territory
        # Assuming 'territory' is a 2D array with 1 indicating owned, 0 unowned
        # Try to move to neighboring cell with 1 (owned territory), prioritizing
        # the direction that increases owned territory component
        directions = [(-1,0),(1,0),(0,-1),(0,1)]
        best_dir = (0,0)
        max_territory_score = -1
        for ddx, ddy in directions:
            nx, ny = my_x + ddx, my_y + ddy
            # Check bounds
            if 0 <= nx < len(territory[0]) and 0 <= ny < len(territory):
                score = territory[ny][nx]
                if score > max_territory_score:
                    max_territory_score = score
                    best_dir = (ddx, ddy)
        dx, dy = best_dir

    else:
        # Default behavior: stay in place
        dx, dy = 0, 0

    # Limit dx, dy to -1, 0, 1 (ensured by assignments)
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]
